WITH monthly_demo AS ( SELECT d.d_year, d.d_month_seq, cd.cd_gender, cd.cd_credit_rating, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(*) AS cnt_returns FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk GROUP BY d.d_year, d.d_month_seq, cd.cd_gender, cd.cd_credit_rating ) SELECT d_year, d_month_seq, cd_gender, cd_credit_rating, total_net_loss, cnt_returns, RANK() OVER (PARTITION BY cd_gender ORDER BY total_net_loss DESC) AS gender_monthly_rank, CASE WHEN total_net_loss > 10000 THEN 'High' WHEN total_net_loss > 5000 THEN 'Medium' ELSE 'Low' END AS loss_category FROM monthly_demo ORDER BY d_year, d_month_seq, cd_gender
